SELECT
  dt.id AS "dt.id",
  CAST(4 * (
    CAST(STRFTIME('%Y', dt.d2) AS INTEGER) - CAST(STRFTIME('%Y', dt.d1) AS INTEGER)
  ) + (
    CAST(CAST((
      CAST(STRFTIME('%m', dt.d2) AS INTEGER) + 2
    ) AS REAL) / 3 AS INTEGER) - CAST(CAST((
      CAST(STRFTIME('%m', dt.d1) AS INTEGER) + 2
    ) AS REAL) / 3 AS INTEGER)
  ) AS INTEGER) AS "v"
FROM dt AS dt
GROUP BY
  dt.id,
  4 * (
    CAST(STRFTIME('%Y', dt.d2) AS INTEGER) - CAST(STRFTIME('%Y', dt.d1) AS INTEGER)
  ) + (
    CAST(CAST((
      CAST(STRFTIME('%m', dt.d2) AS INTEGER) + 2
    ) AS REAL) / 3 AS INTEGER) - CAST(CAST((
      CAST(STRFTIME('%m', dt.d1) AS INTEGER) + 2
    ) AS REAL) / 3 AS INTEGER)
  )
ORDER BY
  "dt.id" ASC NULLS LAST,
  "v" ASC NULLS LAST

