  CAST(CAST(CAST((
    CAST(STRFTIME(
      '%j',
      DATE(
        dt.d1,
        (
          3 - (
            (
              CAST(STRFTIME('%w', dt.d1) AS INTEGER) + 6
            ) % 7
          )
        ) || ' days'
      )
    ) AS INTEGER) - 1
  ) AS REAL) / 7 AS INTEGER) + 1 AS INTEGER) AS "v"
